import re
def nums(s):
 if not s:return None
 o=[]
 for z in s.split(','):
  if not re.fullmatch(r'0|-?[1-9][0-9]*',z):return None
  x=int(z)
  if x < -1000 or x > 1000:return None
  o.append(x)
 return o
def join(a):return ','.join(map(str,a))
def stable_frequencies(s: str) -> str | None:
 a=nums(s)
 if a is None:return None
 return ','.join(f'{x}:{a.count(x)}' for i,x in enumerate(a) if x not in a[:i])
